package shop.ultimatesmp.network.velocity;
import org.junit.jupiter.api.*;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
import com.velocitypowered.api.proxy.*;import com.velocitypowered.api.proxy.server.*;import com.velocitypowered.api.event.connection.*;import com.velocitypowered.api.proxy.messages.*;
import net.kyori.adventure.text.Component;import org.slf4j.Logger;import shop.ultimatesmp.network.*;import java.util.*;import java.net.*;
class ProxyFlowTest {
 ProxyServer proxy;UltimateNetworkProxy handler;List<P> online;
 class P {Player p=mock(Player.class);ServerConnection connection=mock(ServerConnection.class);UUID id=UUID.randomUUID();String name,server;List<Wire> frames=new ArrayList<>();List<String> messages=new ArrayList<>();
  P(String name,String server){this.name=name;this.server=server;when(p.getUniqueId()).thenReturn(id);when(p.getUsername()).thenReturn(name);when(p.getCurrentServer()).thenReturn(Optional.of(connection));when(connection.getPlayer()).thenReturn(p);when(connection.getServerInfo()).thenAnswer(x->new ServerInfo(this.server,new InetSocketAddress("127.0.0.1",25565)));when(connection.sendPluginMessage(any(),any(byte[].class))).thenAnswer(x->{frames.add(Wire.decode(x.getArgument(1)));return true;});doAnswer(x->{messages.add(x.getArgument(0,Component.class).toString());return null;}).when(p).sendMessage(any(Component.class));online.add(this);}
  void state(boolean hidden,String role){emit(this,Wire.of("STATE",id,""+hidden,"true","true","true",role,"true","true","false","false","true","", "0","true"));}
  Wire last(String kind){return frames.stream().filter(f->f.kind().equals(kind)).reduce((a,b)->b).orElseThrow();}
  void command(String...args){emit(this,Wire.of("COMMAND",id,args));clearRate(id);}
 }
 @BeforeEach void setup(){online=new ArrayList<>();proxy=mock(ProxyServer.class);when(proxy.getAllPlayers()).thenAnswer(x->online.stream().map(p->p.p).toList());when(proxy.getPlayer(any(UUID.class))).thenAnswer(x->online.stream().filter(p->p.id.equals(x.getArgument(0))).map(p->p.p).findFirst());handler=new UltimateNetworkProxy(proxy,mock(Logger.class));}
 void emit(P p,Wire f){PluginMessageEvent e=mock(PluginMessageEvent.class);when(e.getIdentifier()).thenReturn(MinecraftChannelIdentifier.from(Wire.CHANNEL));when(e.getSource()).thenReturn(p.connection);when(e.getTarget()).thenReturn(p.p);when(e.getData()).thenReturn(f.encode());handler.message(e);verify(e).setResult(PluginMessageEvent.ForwardResult.handled());}
 void clearRate(UUID id){try{var f=UltimateNetworkProxy.class.getDeclaredField("lastCommand");f.setAccessible(true);((Map<?,?>)f.get(handler)).remove(id);}catch(Exception e){throw new AssertionError(e);}}
 @Test void joinsOnceAndInternalSwitchIsSilent(){P viewer=new P("Viewer","one"),a=new P("Alice","one");viewer.state(false,"MEMBER");a.state(false,"MEMBER");assertEquals(1,viewer.messages.stream().filter(s->s.contains("Alice joined UltimateSMP")).count());a.server="two";a.state(false,"MEMBER");assertEquals(1,viewer.messages.stream().filter(s->s.contains("Alice joined UltimateSMP")).count());DisconnectEvent e=mock(DisconnectEvent.class);when(e.getPlayer()).thenReturn(a.p);online.remove(a);handler.disconnect(e);assertEquals(1,viewer.messages.stream().filter(s->s.contains("Alice left UltimateSMP")).count());}
 @Test void hiddenPlayersDoNotLeakToRosterOrPresence(){P viewer=new P("Viewer","one"),hidden=new P("Secret","two");viewer.state(false,"MEMBER");hidden.state(true,"OWNER");assertTrue(viewer.last("ROSTER").args().stream().noneMatch(s->s.contains("Secret")));assertTrue(viewer.messages.stream().noneMatch(s->s.contains("Secret joined")));viewer.command("tpr","Secret");assertTrue(viewer.messages.stream().anyMatch(s->s.contains("Player not found")));}
 @Test void tpaRequiresRecipientAndLocationSourceThenUsesProtectedMove(){P a=new P("Alice","one"),b=new P("Bob","two"),c=new P("Other","two");a.state(false,"MEMBER");b.state(false,"MEMBER");c.state(false,"MEMBER");assertEquals(b.id,b.last("ACK").actor());a.command("tpr","Bob");c.command("tpraccept","Alice");assertTrue(c.messages.stream().anyMatch(s->s.contains("No matching")));b.command("tpraccept","Alice");Wire locate=b.last("LOCATE");emit(c,new Wire(locate.id(),"LOCATION",c.id,List.of("Overworld","10","64","20","0","0","3","")));assertTrue(a.frames.stream().noneMatch(f->f.kind().equals("MOVE")));emit(b,new Wire(locate.id(),"LOCATION",b.id,List.of("Overworld","10","64","20","0","0","3","")));Wire move=a.last("MOVE");assertEquals(locate.id(),move.id());assertEquals(b.id.toString(),move.at(8));emit(a,new Wire(move.id(),"MOVED",a.id,List.of()));assertTrue(b.messages.stream().anyMatch(s->s.contains("protected inventory handoff")));}
 @Test void memberCannotUseStaffTeleportAndClientCannotSpoofBackend(){P a=new P("Alice","one"),b=new P("Bob","two");a.state(false,"MEMBER");b.state(false,"MEMBER");a.command("tp","Bob");assertTrue(b.frames.stream().noneMatch(f->f.kind().equals("LOCATE")));PluginMessageEvent e=mock(PluginMessageEvent.class);when(e.getIdentifier()).thenReturn(MinecraftChannelIdentifier.from(Wire.CHANNEL));when(e.getSource()).thenReturn(a.p);when(e.getTarget()).thenReturn(a.connection);handler.message(e);verify(e).setResult(PluginMessageEvent.ForwardResult.handled());verify(e,never()).getData();}
 @Test void privateRepliesSpanServersAndRespectDisabledMessages(){P a=new P("Alice","one"),b=new P(".Bedrock","two");a.state(false,"MEMBER");b.state(false,"MEMBER");a.command("msg",".Bedrock","hello");assertTrue(b.messages.stream().anyMatch(s->s.contains("From Alice: hello")));b.command("reply","hi");assertTrue(a.messages.stream().anyMatch(s->s.contains("From .Bedrock: hi")));emit(b,Wire.of("STATE",b.id,"false","false","true","true","MEMBER","true","true","false","false","true","","0","true"));a.command("msg",".Bedrock","blocked");assertTrue(a.messages.stream().anyMatch(s->s.contains("Direct messages are disabled")));}
}
